use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn concat(a: Vec<i32>, b: Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
        forall|i: int| 0 <= i < b.len() ==> result[a.len() + i] == b[i],
{
    let mut result = Vec::with_capacity(a.len() + b.len());
    
    // After creating with capacity, result is empty
    assert(result.len() == 0);
    
    result.extend(&a);
    
    // After first extend, result contains all elements of a
    assert(result.len() == a.len());
    assert(forall|i: int| 0 <= i < a.len() ==> result[i] == a[i]);
    
    result.extend(&b);
    
    // After second extend, result contains all elements of a followed by all elements of b
    assert(result.len() == a.len() + b.len());
    assert(forall|i: int| 0 <= i < a.len() ==> result[i] == a[i]);
    assert(forall|i: int| 0 <= i < b.len() ==> result[a.len() + i] == b[i]);
    
    result
}

} // verus!